let ultimoElementoFocado=null;function abrirModal(){const t=document.getElementById("modal");ultimoElementoFocado=document.activeElement,t.classList.add("aberto"),t.setAttribute("aria-hidden","false");t.querySelector(".modal-fechar").focus()}function fecharModal(){const t=document.getElementById("modal");t.classList.remove("aberto"),t.setAttribute("aria-hidden","true"),ultimoElementoFocado&&ultimoElementoFocado.focus()}function mostrarToast(){const t=document.getElementById("toast");t.classList.add("mostrar"),setTimeout(function(){t.classList.remove("mostrar")},3e3)}document.addEventListener("keydown",function(t){"Escape"===t.key&&fecharModal()});